//! 🧬️ Font-dependent canonical fallback probes original Unicode decomposition without reconstructing text.
use super::{FontMappedScalar,super::{super::{FontFace,FontCmapCursor,FontReader,FontProgress},unicode::{UnicodeLayout,UnicodeMapping,UnicodeMappingCursor,UnicodePropertyCursor,normalize::NormalizedScalar}}};
use semio_framework_value::retirement::{RetireOwned,RetirementCursor};
#[derive(Clone,Copy)]
struct Pending{scalar:u32,depth:usize}
#[derive(semio_framework_value::RetireOwned)]
struct Owners{output:Vec<FontMappedScalar>,failure:Option<String>}
pub struct FontCanonicalScalarCursor{owners:Owners,face:FontFace,font_pointer:usize,unicode_pointer:usize,layout:UnicodeLayout,source_at:usize,pending:[Pending;256],pending_count:usize,current:Pending,phase:u8,mapper:Option<FontCmapCursor>,mapping:Option<UnicodeMappingCursor>,property:Option<UnicodePropertyCursor>,glyph:u16,expand_first:usize,expand_at:usize,hangul:[u32;3],hangul_count:usize,work:u64,max_work:u64,covered:bool,cancelled:bool}
impl RetireOwned for FontCanonicalScalarCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.owners.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.owners.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl FontCanonicalScalarCursor{
 pub fn new(face:FontFace,font:&[u8],layout:UnicodeLayout,unicode:&[u8],source:NormalizedScalar,max_work:u64)->Self{let mut pending=[Pending{scalar:0,depth:0};256];pending[0]=Pending{scalar:source.scalar,depth:0};Self{owners:Owners{output:Vec::new(),failure:(!(1..=1000000000).contains(&max_work)).then(||"Invalid canonical font scalar policy".into())},face,font_pointer:font.as_ptr()as usize,unicode_pointer:unicode.as_ptr()as usize,layout,source_at:source.source_at,pending,pending_count:1,current:pending[0],phase:0,mapper:None,mapping:None,property:None,glyph:0,expand_first:0,expand_at:0,hangul:[0;3],hangul_count:0,work:0,max_work,covered:true,cancelled:false}}
 fn push(&mut self,scalar:u32)->Result<(),String>{if self.pending_count==256||self.current.depth==32{return Err("Canonical font decomposition depth exceeded".into());}self.pending[self.pending_count]=Pending{scalar,depth:self.current.depth+1};self.pending_count+=1;Ok(())}
 fn step(&mut self,font:&[u8],unicode:&[u8])->Result<(),String>{if font.len()!=self.face.byte_length||font.as_ptr()as usize!=self.font_pointer||unicode.len()!=self.layout.byte_length||unicode.as_ptr()as usize!=self.unicode_pointer{return Err("Original canonical font source changed".into());}let r=FontReader::whole(unicode);match self.phase{0=>{self.owners.output.try_reserve_exact(64).map_err(|_|"Canonical font output admission refused")?;self.phase=1;},1=>{if self.pending_count==0{self.phase=7;return Ok(());}self.pending_count-=1;self.current=self.pending[self.pending_count];self.mapper=Some(FontCmapCursor::new(self.face,self.current.scalar)?);self.phase=2;},2=>{if !self.mapper.as_mut().unwrap().step(font)?{return Ok(());}self.glyph=self.mapper.take().unwrap().result()?;self.property=Some(UnicodePropertyCursor::new(self.layout,self.current.scalar)?);self.phase=3;},3=>{if !self.property.as_mut().unwrap().step(unicode)?{return Ok(());}let property=self.property.take().unwrap().result()?;if self.glyph!=0||property.flags&1!=0{if self.owners.output.len()==64{return Err("Canonical font scalar expansion exceeded".into());}self.owners.output.push(FontMappedScalar{glyph:self.glyph,scalar:self.current.scalar,source_at:self.source_at,property});self.phase=1;return Ok(());}let value=self.current.scalar;if (0xac00..0xd7a4).contains(&value){let s=value-0xac00;let t=s%28;self.hangul=[0x1100+s/588,0x1161+s%588/28,0x11a7+t];self.hangul_count=if t>0{3}else{2};self.expand_at=self.hangul_count;self.phase=6;}else{self.mapping=Some(UnicodeMappingCursor::new(self.layout,UnicodeMapping::Decomposition,value,0));self.phase=4;}},4=>{if !self.mapping.as_mut().unwrap().step(unicode)?{return Ok(());}let at=self.mapping.take().unwrap().result()?;if let Some(at)=at.filter(|at|r.u32(*at+12).ok()==Some(0)){self.expand_first=r.u32(at+4)?as usize;self.expand_at=r.u32(at+8)?as usize;self.phase=5;}else{self.covered=false;self.phase=7;}},5=>{if self.expand_at==0{self.phase=1;return Ok(());}self.expand_at-=1;self.push(r.u32(self.layout.offsets[3]+(self.expand_first+self.expand_at)*4)?)?;},6=>{if self.expand_at==0{self.phase=1;return Ok(());}self.expand_at-=1;self.push(self.hangul[self.expand_at])?;},_=>return Err("Canonical font scalar stage invalid".into())}Ok(())}
 pub fn advance(&mut self,font:&[u8],unicode:&[u8],grant:usize)->Result<FontProgress,String>{if grant==0{return Err("Invalid canonical font scalar grant".into());}if self.cancelled{return Err("Canonical font scalar cancelled".into());}if let Some(error)=&self.owners.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==7{break;}if self.work==self.max_work{self.owners.failure=Some("Canonical font scalar work exceeded".into());return Err(self.owners.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(font,unicode){self.owners.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(FontProgress{phase:match self.phase{0=>"admission",1=>"scalar",2=>"cmap",3=>"property",4=>"decomposition",5|6=>"expand",_=>"complete"},work:self.work,done:self.phase==7})}
 pub fn take_result(&mut self)->Result<Option<Vec<FontMappedScalar>>,String>{if self.phase!=7||self.cancelled||self.owners.failure.is_some(){return Err("Canonical font scalar incomplete".into());}Ok(self.covered.then(||std::mem::take(&mut self.owners.output)))}
 pub fn cancel(&mut self){self.cancelled=true;}
}
